36	static void void_noop_sps_wrapper(orc_rt_SessionRef S,
37	                                  orc_rt_WrapperFunctionBuffer ArgBytes,
38	                                  orc_rt_WrapperFunctionReturn Return,
39	                                  uint64_t CallId) {
