97	static void round_trip_string_via_span_sps_wrapper(
98	    orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
99	    orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {
