119	static void improbable_feat_sps_wrapper(orc_rt_SessionRef S,
120	                                        orc_rt_WrapperFunctionBuffer ArgBytes,
121	                                        orc_rt_WrapperFunctionReturn Return,
122	                                        uint64_t CallId) {
