156	static void halve_number_sps_wrapper(orc_rt_SessionRef S,
157	                                     orc_rt_WrapperFunctionBuffer ArgBytes,
158	                                     orc_rt_WrapperFunctionReturn Return,
159	                                     uint64_t CallId) {
