170	TEST(SPSWrapperFunctionUtilsTest, TransparentConversionExpectedSuccessCase) {
171	  int32_t Result = 0;
172	  SPSWrapperFunction<SPSExpected<int32_t>(int32_t)>::call(
173	      DirectCaller(nullptr, halve_number_sps_wrapper),
174	      [&](Expected<Expected<int32_t>> R) {
175	        Result = cantFail(cantFail(std::move(R)));
176	      },
177	      2);
178	
179	  EXPECT_EQ(Result, 1);
