183	  std::string ErrMsg;
184	  SPSWrapperFunction<SPSExpected<int32_t>(int32_t)>::call(
185	      DirectCaller(nullptr, halve_number_sps_wrapper),
186	      [&](Expected<Expected<int32_t>> R) {
187	        ErrMsg = toString(cantFail(std::move(R)).takeError());
