211	/// Provides call and handle utilities to simplify writing and invocation of
212	/// wrapper functions in C++.
213	struct WrapperFunction {
214	
215	  /// Wraps an asynchronous method (a method returning void, and taking a
216	  /// return callback as its first argument) for use with
217	  /// WrapperFunction::handle.
218	  ///
219	  /// AsyncMethod's call operator takes an ExecutorAddr as its second argument,
220	  /// casts it to a ClassT*, and then calls the wrapped method on that pointer,
221	  /// forwarding the return callback and any subsequent arguments (after the
222	  /// second argument representing the object address).
223	  ///
224	  /// This utility removes some of the boilerplate from writing wrappers for
225	  /// method calls.
226	  template <typename ClassT, typename ReturnT, typename... ArgTs>
227	  struct AsyncMethod {
228	    AsyncMethod(void (ClassT::*M)(ReturnT, ArgTs...)) : M(M) {}
229	    void operator()(ReturnT &&Return, ExecutorAddr Obj, ArgTs &&...Args) {
230	      (Obj.toPtr<ClassT *>()->*M)(std::forward<ReturnT>(Return),
231	                                  std::forward<ArgTs>(Args)...);
232	    }
233	
234	  private:
235	    void (ClassT::*M)(ReturnT, ArgTs...);
236	  };
237	
238	  /// Create an AsyncMethod wrapper for the given method pointer. The given
239	  /// method should be asynchronous: returning void, and taking a return
240	  /// callback as its first argument.
241	  ///
242	  /// The handWithAsyncMethod function can be used to remove some of the
243	  /// boilerplate from writing wrappers for method calls:
244	  ///
245	  ///   @code{.cpp}
246	  ///   class MyClass {
247	  ///   public:
248	  ///     void myMethod(move_only_function<void(std::string)> Return,
249	  //                    uint32_t X, bool Y) { ... }
250	  ///   };
251	  ///
252	  ///   // SPS Method signature -- note MyClass object address as first
253	  ///   // argument.
254	  ///   using SPSMyMethodWrapperSignature =
255	  ///     SPSString(SPSExecutorAddr, uint32_t, bool);
256	  ///
257	  ///
258	  ///   static void adder_add_async_sps_wrapper(
259	  ///       orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
260	  ///       orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {
261	  ///     using SPSSig = SPSString(SPSExecutorAddr, int32_t, bool);
262	  ///     SPSWrapperFunction<SPSSig>::handle(
263	  ///         S, ArgBytes, Return, CallId,
264	  ///         WrapperFunction::handleWithAsyncMethod(&MyClass::myMethod));
265	  ///   }
266	  ///   @endcode
267	  ///
268	  template <typename ClassT, typename ReturnT, typename... ArgTs>
269	  static AsyncMethod<ClassT, ReturnT, ArgTs...>
270	  handleWithAsyncMethod(void (ClassT::*M)(ReturnT, ArgTs...)) {
271	    return AsyncMethod<ClassT, ReturnT, ArgTs...>(M);
272	  }
273	
274	  /// Wraps a synchronous method (an ordinary method that returns its result,
275	  /// as opposed to an asynchronous method, see AsyncMethod) for use with
276	  /// WrapperFunction::handle.
277	  ///
278	  /// SyncMethod's call operator takes a return callback as its first argument
279	  /// and an ExecutorAddr as its second argument. The ExecutorAddr argument is
280	  /// cast to a ClassT*, and then called passing the subsequent arguments
281	  /// (after the second argument representing the object address). The Return
282	  /// callback is then called on the value returned from the method.
283	  ///
284	  /// This utility removes some of the boilerplate from writing wrappers for
285	  /// method calls.
286	  template <typename ClassT, typename RetT, typename... ArgTs>
287	  class SyncMethod {
288	  public:
289	    SyncMethod(RetT (ClassT::*M)(ArgTs...)) : M(M) {}
290	
291	    void operator()(move_only_function<void(RetT)> Return, ExecutorAddr Obj,
292	                    ArgTs &&...Args) {
293	      Return((Obj.toPtr<ClassT *>()->*M)(std::forward<ArgTs>(Args)...));
294	    }
295	
296	  private:
297	    RetT (ClassT::*M)(ArgTs...);
298	  };
299	
300	  /// Create an SyncMethod wrapper for the given method pointer. The given
301	  /// method should be synchronous, i.e. returning its result (as opposed to
302	  /// asynchronous, see AsyncMethod).
303	  ///
304	  /// The handWithAsyncMethod function can be used to remove some of the
305	  /// boilerplate from writing wrappers for method calls:
306	  ///
307	  ///   @code{.cpp}
308	  ///   class MyClass {
309	  ///   public:
310	  ///     std::string myMethod(uint32_t X, bool Y) { ... }
311	  ///   };
312	  ///
313	  ///   // SPS Method signature -- note MyClass object address as first
314	  ///   // argument.
315	  ///   using SPSMyMethodWrapperSignature =
316	  ///     SPSString(SPSExecutorAddr, uint32_t, bool);
317	  ///
318	  ///
319	  ///   static void adder_add_sync_sps_wrapper(
320	  ///       orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
321	  ///       orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {
322	  ///     using SPSSig = SPSString(SPSExecutorAddr, int32_t, bool);
323	  ///     SPSWrapperFunction<SPSSig>::handle(
324	  ///         S, ArgBytes, Return, CallId,
325	  ///         WrapperFunction::handleWithSyncMethod(&Adder::addSync));
326	  ///   }
327	  ///   @endcode
328	  ///
329	  template <typename ClassT, typename RetT, typename... ArgTs>
330	  static SyncMethod<ClassT, RetT, ArgTs...>
331	  handleWithSyncMethod(RetT (ClassT::*M)(ArgTs...)) {
332	    return SyncMethod<ClassT, RetT, ArgTs...>(M);
333	  }
334	
335	  /// Make a call to a wrapper function.
336	  ///
337	  /// This utility serializes and deserializes arguments and return values
338	  /// (using the given Serializer), and calls the wrapper function via the
339	  /// given Caller object.
340	  template <typename Caller, typename Serializer, typename ResultHandler,
341	            typename... ArgTs>
342	  static void call(Caller &&C, Serializer &&Z, ResultHandler &&RH,
343	                   ArgTs &&...Args) {
344	    typedef CallableArgInfo<ResultHandler> ResultHandlerTraits;
345	    static_assert(std::is_void_v<typename ResultHandlerTraits::return_type>,
346	                  "Result handler should return void");
347	    static_assert(
348	        std::tuple_size_v<typename ResultHandlerTraits::args_tuple_type> == 1,
349	        "Result-handler should have exactly one argument");
350	    typedef typename ResultHandlerTraits::args_tuple_type ResultTupleType;
351	
352	    if (auto ArgBytes = Z.arguments().serialize(std::forward<ArgTs>(Args)...)) {
353	      C(
354	          [RH = std::move(RH),
355	           Z = std::move(Z)](WrapperFunctionBuffer ResultBytes) mutable {
356	            if (const char *ErrMsg = ResultBytes.getOutOfBandError())
357	              RH(make_error<StringError>(ErrMsg));
358	            else
359	              RH(detail::ResultDeserializer<ResultTupleType, Serializer>::
360	                     deserialize(std::move(ResultBytes), Z));
361	          },
362	          std::move(*ArgBytes));
363	    } else
364	      RH(make_error<StringError>(
365	          "Could not serialize wrapper function call arguments"));
366	  }
367	
368	  /// Simplifies implementation of wrapper functions in C++.
369	  ///
370	  /// This utility deserializes and serializes arguments and return values
371	  /// (using the given Serializer), and calls the given handler.
372	  template <typename Serializer, typename Handler>
373	  static void handle(orc_rt_SessionRef S, WrapperFunctionBuffer ArgBytes,
374	                     orc_rt_WrapperFunctionReturn Return, uint64_t CallId,
375	                     Serializer &&Z, Handler &&H) {
376	    typedef detail::WFHandlerTraits<Handler> HandlerTraits;
377	    typedef typename HandlerTraits::ArgTupleType ArgTuple;
378	    typedef typename HandlerTraits::YieldType Yield;
379	    static_assert(std::is_void_v<typename CallableArgInfo<Yield>::return_type>,
380	                  "Return callback must return void");
381	    typedef typename CallableArgInfo<Yield>::args_tuple_type RetTupleType;
382	
383	    if (ArgBytes.getOutOfBandError())
384	      return Return(S, ArgBytes.release(), CallId);
385	
386	    if (auto Args = Z.arguments().template deserialize<ArgTuple>(ArgBytes))
387	      std::apply(HandlerTraits::forwardArgsAsRequested(bind_front(
388	                     std::forward<Handler>(H),
389	                     detail::StructuredYield<RetTupleType, Serializer>(
390	                         S, Return, CallId, std::move(Z)))),
391	                 *Args);
392	    else
393	      Return(S,
394	             WrapperFunctionBuffer::createOutOfBandError(
395	                 "Could not deserialize wrapper function arg data")
396	                 .release(),
397	             CallId);
398	  }
399	};
400	
401	} // namespace orc_rt
